let style=['Boxer','Wrestler'].includes(saved.style)?saved.style:'Boxer',game=new Arena(style,saved),paused=false,held=false,move={x:0,y:0},keys=new Set(),last=0,toastTime=0,audio=null,sound=false,stickId=null,W=0,H=0,S=30;
function resize(){const d=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*d;canvas.height=H*d;ctx.setTransform(d,0,0,d,0,0);S=Math.min(W/28,H/16);if(H>W&&game.state==='fight')setPause(true);}addEventListener('resize',resize);resize();
